import {state,initialize,enterPreview,signIn,signOut,saveProfile,createProject,selectProject,joinRoom,list,put,remove,canEdit,inviteMember,projectInvitations,cancelInvitation,requestLoginLink,setAccountPassword,updateProject,projectMembers,projectBackup,validateBackup,id} from './store.js';
import {canvasHTML,bindCanvas} from './canvas.js';
const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rooms=[['dev','01','開発部屋','コードを育てる','💻','green'],['design','02','デザイン部屋','画面を一緒に描く','🎨','blue'],['scrum','03','スクラム部屋','計画して、振り返る','📋','orange'],['library','04','資料部屋','知識と道具の棚','📚','purple'],['meeting','05','会議室','話して、記録する','📅','red'],['communication','06','コミュニケーションルーム','テーマごとに会話する','💬','blue'],['study','07','勉強部屋','自分のペースで学ぶ','📖','green'],['presentation','08','プレゼンルーム','伝わる資料をつくる','📽️','purple'],['environment','--','環境委員会','開発の準備を整える','🛠️','yellow']];
let currentProject=null,currentRoom='campus',subtab='board',cleanup=null,rendering=false;
const safeUrl=v=>{try{const u=new URL(v);return u.protocol==='https:'?u.href:''}catch{return ''}};
const avatar=(index=0,name='',large=false)=>`<span class="avatar ${large?'large':''}" style="background-position:${Number(index)%5*25}% ${Math.floor(Number(index)/5)*20}%" aria-label="${esc(name)}">${esc(name?.slice(0,1)||'学')}</span>`;
export function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
export function download(name,content,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function dialog(title,body,submit,label='保存'){const modal=$('#modal');modal.innerHTML=`<form id="modal-form"><div class="dialog-head"><h2>${esc(title)}</h2><button type="button" class="icon-button" data-close aria-label="閉じる">×</button></div><div class="dialog-body">${body}</div><p class="form-error" role="alert"></p><div class="dialog-footer"><button type="button" data-close>キャンセル</button><button class="primary" type="submit">${esc(label)}</button></div></form>`;modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());modal.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const result=await submit(new FormData(event.target));if(result!==false)modal.close()}catch(e){modal.querySelector('.form-error').textContent=e.message}finally{button.disabled=false}};modal.showModal();}
const input=(name,label,value='',type='text',required=false)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
const textArea=(name,label,value='')=>`<label>${label}<textarea name="${name}" rows="4">${esc(value)}</textarea></label>`;
const select=(name,label,options,value)=>`<label>${label}<select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></label>`;
function route(){const params=new URLSearchParams(location.hash.slice(1));return {p:params.get('p'),r:params.get('r')||'campus',tab:params.get('tab'),item:params.get('item')}}
function navigate(room,project=currentProject?.id,tab,item){const p=new URLSearchParams();if(project)p.set('p',project);p.set('r',room);if(tab)p.set('tab',tab);if(item)p.set('item',item);const hash='#'+p; if(location.hash===hash)activate();else location.hash=hash;}
async function share(room=currentRoom,item){if(location.protocol==='file:'){notify('このファイルは端末内プレビューです。共有URLはWeb公開後に利用できます。');return}const params=new URLSearchParams({r:room});if(currentProject)params.set('p',currentProject.id);if(item)params.set('item',item);if(room==='scrum')params.set('tab',subtab);const url=location.origin+location.pathname+'#'+params;try{await navigator.clipboard.writeText(url);notify(state.preview?'URLをコピーしました。プレビューのデータは他の端末に共有されません。':'共有URLをコピーしました。閲覧にはプロジェクトの権限が必要です。')}catch{dialog('共有URL',`<label>URL<input readonly value="${esc(url)}"></label>`,async()=>{},'閉じる')}}
function shell(content){const total=list('task',currentProject?.id),done=total.filter(e=>e.payload.status==='done').length;$('#app').innerHTML=`<aside class="sidebar ${localStorage.getItem('des-sidebar-collapsed')==='1'?'collapsed':''}"><button id="sidebar-toggle" class="sidebar-toggle" title="メニューを折り畳む・展開する" aria-label="メニューを折り畳む・展開する">☰</button><a class="brand" href="#r=campus"><span class="brand-mark">DE</span><span>デジタル<br>エンジニア学校<small>DIGITAL ENGINEER SCHOOL</small></span></a><div class="term-label">共同開発キャンパス</div><button class="nav-item ${currentRoom==='campus'?'active':''}" data-room="campus"><span>🏫</span><span class="nav-label">校内案内</span></button><div class="section-label">教室に入る</div>${rooms.filter(r=>r[0]!=='environment').map(r=>`<button class="nav-item ${currentRoom===r[0]?'active':''}" data-room="${r[0]}" title="${r[2]}" aria-label="${r[2]}"><span>${r[4]}</span><span class="nav-label">${r[2]}</span><small>${r[1]}</small></button>`).join('')}<div class="section-label committee-label">学校運営・サポート</div><button class="nav-item ${currentRoom==='environment'?'active':''}" data-room="environment" title="環境委員会" aria-label="環境委員会"><span>🛠️</span><span class="nav-label">環境委員会</span></button><div class="sidebar-bottom"><div class="student-card">${avatar(state.profile?.avatar,state.profile?.name)}<div><strong>${esc(state.profile?.name)}</strong><small>共同開発の生徒</small></div><button class="icon-button" data-action="profile" aria-label="プロフィールを編集">⚙</button></div><button class="quiet" data-action="logout">${state.preview?'プレビューを退出':'ログアウト'}</button></div></aside><div class="school-main"><header class="topbar"><div class="breadcrumb"><button class="breadcrumb-home" data-room="campus">校内ホーム</button> <span>/</span> ${esc(currentRoom==='campus'?'校内案内':rooms.find(r=>r[0]===currentRoom)?.[2])}</div><div class="top-actions"><span class="mode-badge ${state.preview?'preview':''}" id="connection">${state.preview?'端末内プレビュー':'共同利用'}</span><div class="presence" id="presence">${avatar(state.profile?.avatar,state.profile?.name)}</div><button data-action="share">URLを共有</button></div></header><main>${state.preview?'<div class="preview-banner">体験モード · この端末だけに保存されます。ログイン・2人の同期・アクセス制御は接続後に利用できます。<button data-action="setup">接続方法</button></div>':''}<div class="project-strip"><div><span class="section-label">作業中のプロジェクト</span><select id="project-selector" aria-label="プロジェクトを選ぶ"><option value="">選択してください</option>${state.projects.map(p=>`<option value="${p.id}" ${currentProject?.id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><span class="tag">${currentProject?.visibility==='public'?'学校内Public':'Private'}</span><span class="muted">${currentProject?`${done} / ${total.length} タスク完了`:''}</span><button data-action="newProject">＋ プロジェクトを作る</button>${currentProject&&state.role==='owner'?'<button data-action="invite">共同開発者を招待</button><button data-action="projectSettings">プロジェクト設定</button>':''}</div>${currentProject?'<div class="project-tools"><button data-action="members">メンバー・権限</button><button data-action="backup">バックアップを書き出す</button><button data-action="restore">バックアップから新規作成</button></div>':''}<div id="hallway-roster" class="hallway-roster"></div>${content}<footer>デジタルエンジニア学校 <span>部署を超えて、一緒につくる。</span></footer></main></div>`;
 $('#sidebar-toggle').onclick=()=>{const side=$('.sidebar');side.classList.toggle('collapsed');localStorage.setItem('des-sidebar-collapsed',side.classList.contains('collapsed')?'1':'0');};
 $$('[data-room]').forEach(b=>b.onclick=()=>navigate(b.dataset.room,currentProject?.id,b.dataset.roomTab));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$('#project-selector').onchange=e=>navigate(currentRoom,e.target.value||null);
}
function campus(){const tasks=list('task',currentProject?.id),progress=tasks.length?Math.round(tasks.filter(t=>t.payload.status==='done').length/tasks.length*100):0;return `<div class="page-heading"><div><div class="eyebrow">SCHOOL GUIDE / 校内案内</div><h1>おかえりなさい、デジタル学校へ。</h1><p>教室を選んで、チームの作業をはじめましょう。</p></div><div class="date-stamp"><span>${new Intl.DateTimeFormat('ja-JP',{month:'long'}).format(new Date())}</span><strong>${new Date().getDate()}</strong><small>${new Intl.DateTimeFormat('ja-JP',{weekday:'long'}).format(new Date())}</small></div></div><section class="storybook-campus" aria-label="緑に囲まれた手描きの学校"><div class="campus-caption"><span>森のそばの、ものづくり学校</span><h2>アイデアを持ち寄って、<br>今日も一緒につくろう。</h2><p>開発も、デザインも、ひとつの校舎で。</p><button data-room="design">デザイン部屋の扉を開ける →</button></div></section><section class="student-home"><div class="home-student">${avatar(state.profile?.avatar,'',true)}<div><span class="section-label">MY SCHOOL / 入校後ホーム</span><h2>今日の開発をはじめよう。</h2><p>教室へ移動するか、作業中のプロジェクトを続けられます。</p></div></div><div class="home-shortcuts"><button class="primary" data-room="dev">開発机へ</button><button data-room="design">デザインを描く</button><button data-room="scrum">タスクを確認</button><button data-room="communication">テーマで話す</button><button data-room="study">勉強をはじめる</button><button data-room="presentation">プレゼンを準備</button></div></section><section class="school-floor"><div class="floor-guide"><div><span class="section-label">CAMPUS MAP</span><h2>校舎の教室案内</h2><p>好きな教室の扉を開けて、共同開発をはじめよう。</p></div><span class="floor-sign">共同開発棟 · 1F</span></div>${campusSceneHTML(rooms.filter(r=>r[0]!=='environment'))}</section><section class="committee-desk"><div><span class="section-label">学校運営・サポート</span><h2>🛠️ 環境委員会</h2><p>VSCode・Gitの準備と、AIスキルの使い方を確認できます。</p></div><button data-room="environment">手順書・スキルを開く →</button></section><div class="section-heading"><h2>今日のホームルーム</h2><span class="muted">進捗とチームの約束を確認</span></div><div class="campus-top"><section class="chalkboard"><span class="chalk-label">CLASSROOM BLACKBOARD</span><h2>${esc(currentProject?.name||'プロジェクトを作りましょう')}</h2><p>${esc(currentProject?.description||'最初にPrivate / Publicを選んで、共同開発を始められます。')}</p><div class="chalk-metrics"><div><strong>${tasks.filter(t=>t.payload.status==='doing').length}</strong><span>進行中のタスク</span></div><div><strong>${tasks.filter(t=>t.payload.status==='done').length}</strong><span>完了したタスク</span></div><div><strong>${progress}<small>%</small></strong><span>タスクの進捗</span></div></div><div class="chalk-line"><i style="width:${progress}%"></i></div><button class="chalk-button" data-action="openBoard">スクラムボードを開く</button></section><section class="noticeboard"><span class="section-label">校内掲示板</span><h2>チームの約束</h2><div class="paper yellow-paper"><span class="pin"></span><strong>一日の最後はcommit & push</strong><p>作業の続きが、明日の自分と仲間に伝わるように。</p></div><div class="paper"><span class="pin"></span><strong>小さく作って、早く共有</strong><p>困ったことはタスクに残して、教室で相談しよう。</p></div><button class="text-button" data-action="openRules">開発ルールを読む</button></section></div><div class="section-heading"><h2>プロジェクトの掲示</h2><button data-action="refresh">最新の一覧を取得</button></div><div class="projects-grid">${state.projects.map(p=>`<button class="project-card" data-project="${p.id}"><div class="row"><span class="tag">${p.visibility==='public'?'学校内Public':'Private'}</span><small>プロジェクト掲示</small></div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p></button>`).join('')||'<div class="empty">まだプロジェクトがありません。最初のプロジェクトを作成してください。</div>'}</div>`}
const heading=(room,extra='')=>{const r=rooms.find(r=>r[0]===room);return `<div class="page-heading"><div><div class="eyebrow">ROOM ${r[1]} / ${r[3]}</div><h1 class="classroom-title">${r[2]}</h1></div><div class="room-heading-actions"><button data-room="campus">← 校内ホームに戻る</button>${extra}</div></div><nav class="room-path" aria-label="教室の作業導線"><span>この教室でできること</span>${(room==='dev'?[['openEditor','エディターを開く'],['clone','clone手順']]:room==='design'?[]:room==='scrum'?[]:room==='library'?[['newResource','資料を棚に追加']]:room==='meeting'?[['newMeeting','会議・議事録を作成']]:[]).map(([a,l])=>`<button data-action="${a}" ${a==='openEditor'||a==='clone'?(!currentProject?.repo?'disabled':''):(canEdit()?'':'disabled')}>${l}</button>`).join('')}<button data-room="${room==='dev'?'environment':room==='environment'?'dev':room==='design'?'scrum':room==='scrum'?'meeting':room==='meeting'?'scrum':room==='library'?'presentation':room==='presentation'?'library':'design'}">${room==='dev'?'環境構築の手順へ':room==='environment'?'準備を終えて開発部屋へ':room==='design'?'設計からタスク管理へ':room==='scrum'?'会議室で相談する':room==='meeting'?'決定事項をタスク管理へ':room==='library'?'プレゼンのテンプレートを選ぶ':room==='presentation'?'仕様書・スキルの棚へ':'資料を見てデザインへ'} →</button></nav>`};
function tasksHTML(){const tasks=list('task',currentProject.id);return `<div class="section-heading"><div><h2>スクラムボード</h2><p class="muted">エピックでまとめて、カードで進める。</p></div><button class="primary" data-action="newTask" ${canEdit()?'':'disabled'}>＋ カードを追加</button></div><div class="kanban">${[['todo','これから'],['doing','進行中'],['review','レビュー'],['done','完了']].map(([status,name])=>`<section class="kanban-column" data-status="${status}"><div class="column-title"><span class="status-dot ${status}"></span><h3>${name}</h3><span>${tasks.filter(t=>t.payload.status===status).length}</span></div>${tasks.filter(t=>t.payload.status===status).map(taskHTML).join('')||'<div class="column-empty">ここにカードを移動</div>'}</section>`).join('')}</div>`}
function taskHTML(e){const p=e.payload;return `<article class="task-card" draggable="${canEdit()}" data-task="${e.id}" tabindex="0" role="button" aria-label="タスク ${esc(p.title)}"><div class="row"><span class="task-type">${p.type==='epic'?'EPIC':'TASK'}</span><span class="priority ${esc(p.priority)}">${{high:'高',normal:'通常',low:'低'}[p.priority]||'通常'}</span></div><h3>${esc(p.title)}</h3>${p.epic?`<span class="epic-label">${esc(state.entities.find(e=>e.id===p.epic)?.payload.title||'エピック')}</span>`:''}<p>${esc(p.description?.slice(0,90))}</p><div class="task-foot"><span>${esc(p.assignee||'担当未定')}</span><small>${esc(p.due||'期限未設定')}</small></div></article>`}
function scrum(){return heading('scrum')+`<nav class="scrum-entry" aria-label="スクラムの作業"><button data-room="scrum" data-room-tab="board">タスクを進める</button><button data-room="scrum" data-room-tab="refine">アイデアを整理する</button><button data-room="scrum" data-room-tab="retro">スプリントを振り返る</button></nav>`+`<div class="tabs" role="tablist">${[['board','スクラムボード'],['refine','リファイメントキャンバス'],['retro','レトロスペクティブ']].map(([v,n])=>`<button role="tab" aria-selected="${subtab===v}" data-tab="${v}" class="${subtab===v?'active':''}">${n}</button>`).join('')}</div>`+(subtab==='refine'?canvasHTML('refine',currentProject.id):subtab==='retro'?retroHTML():tasksHTML())}
function retroHTML(){return `<div class="section-heading"><div><h2>スプリントの振り返り</h2><p class="muted">Keep / Problem / Tryで、次の一歩を決める。</p></div><button class="primary" data-action="newRetro" ${canEdit()?'':'disabled'}>＋ 付箋を追加</button></div><div class="retro-grid">${[['keep','Keep','続けたいこと'],['problem','Problem','困ったこと'],['try','Try','次に試すこと']].map(([key,title,desc])=>`<section class="retro-column ${key}"><h2>${title}</h2><p>${desc}</p>${list('retro',currentProject.id).filter(e=>e.payload.column===key).map(e=>`<article class="retro-note"><button class="quiet note-edit" data-retro-edit="${e.id}">${esc(e.payload.text)}</button><small>${esc(e.payload.sprint||'スプリント未設定')} · ${esc(e.payload.author)}</small><div class="row"><button data-vote="${e.id}" ${canEdit()?'':'disabled'}>賛成 ${e.payload.votes?.length||0}</button>${key==='try'?`<button data-to-task="${e.id}" ${canEdit()?'':'disabled'}>タスクにする</button>`:''}</div></article>`).join('')}</section>`).join('')}</div>`}
function dev(){const drafts=list('code',currentProject.id);return heading('dev',`<button data-action="repo" ${canEdit()?'':'disabled'}>リポジトリを設定</button>`)+`<div class="dev-layout"><section class="panel"><div class="section-heading"><h2>開発机</h2><span class="tag">${currentProject.repo?'GitHub連携先あり':'未接続'}</span></div><p>${esc(currentProject.repo||'GitHubリポジトリを登録して、開発環境を開きましょう。')}</p><div class="row wrap"><button class="primary" data-action="openEditor" ${currentProject.repo?'':'disabled'}>ブラウザエディター</button><button data-action="codespaces" ${currentProject.repo?'':'disabled'}>Codespaces</button><button data-action="clone" ${currentProject.repo?'':'disabled'}>clone手順</button></div><div class="divider"></div><div class="section-heading"><h3>校内コード下書き</h3><button data-action="newCode" ${canEdit()?'':'disabled'}>＋ ファイル</button></div><p class="muted">下書きは学校に保存。GitHubへのcommit・pushは開発環境から行います。</p><div id="branch-state" class="branch-state"></div><div class="code-workspace"><button type="button" class="workspace-expand" data-expand="code-workspace">⛶ 作業スペースを拡大</button><nav>${drafts.map(e=>`<button data-code="${e.id}">▱ ${esc(e.payload.path)}</button>`).join('')||'<small>ファイルを追加してください。</small>'}</nav><div id="code-editor"><div class="empty">左のファイルを選んで編集</div></div></div><section class="school-terminal"><div class="section-heading"><h3>⌨ 開発ターミナル</h3><button data-action="codespaces" ${currentProject.repo?'':'disabled'}>Gitを実行する環境を開く ↗</button></div><p>GitHub参照用のコマンドパネルです。PowerShellの実行環境ではありません。clone・commit・pushはCodespaces / VSCodeで実行してください。</p><div id="terminal-output" role="log" aria-label="コマンド実行結果" tabindex="0"></div><form id="terminal-form"><label for="terminal-command">PS 学校\開発机&gt;</label><input id="terminal-command" autocomplete="off" spellcheck="false" placeholder="help または git branch" maxlength="500"><button>実行</button></form></section></section><aside><section class="noticeboard"><span class="section-label">開発ルール掲示板</span><h2>教室の約束</h2><ol class="rules"><li>開始前に最新の変更を取得</li><li>作業ごとにブランチを作る</li><li>一日の最後にcommit & push</li><li>mainへはPRとレビューで反映</li><li>秘密情報はコードに書かない</li><li>完了条件と結果をタスクに残す</li></ol></section><section class="panel git-guide"><h3>Gitコマンド帳</h3>${[['git clone <URL>','リポジトリを手元に複製'],['git switch -c feature/name','作業用ブランチを作る'],['git status','変更状態を確認'],['git diff','変更内容を確認'],['git add <file>','記録するファイルを選ぶ'],['git commit -m "内容"','変更を履歴に記録'],['git push -u origin <branch>','作業ブランチを共有'],['git pull --ff-only','最新の変更を取り込む']].map(([cmd,desc])=>`<div><code>${esc(cmd)}</code><small>${desc}</small></div>`).join('')}</section></aside></div>`}
function library(){return heading('library',`<button class="primary" data-action="newResource" ${canEdit()?'':'disabled'}>＋ 棚に追加</button>`)+`<div class="shelves">${[['slides','プレゼン資料の棚','発表・進捗報告・ロードマップ'],['spec','仕様書の棚','要件・画面・API・受入条件'],['skill','AIスキルの棚','エージェントへの作業手順']].map(([kind,name,desc])=>`<section class="shelf"><div class="shelf-heading"><span>▥</span><div><h2>${name}</h2><p>${desc}</p></div></div><div class="shelf-items">${kind==='slides'?'<a class="resource-book mustard" href="templates/school-presentation.pptx" download><span>PPTX</span><strong>校内プレゼン<br>テンプレート</strong><small>進捗報告・構成・ロードマップ</small></a>':kind==='spec'?'<a class="resource-book blue" href="templates/system-specification.docx" download><span>WORD</span><strong>システム仕様書<br>テンプレート</strong><small>要件・画面・API・受入条件</small></a>':'<a class="resource-book green" href="templates/SKILL.md" download><span>SKILL</span><strong>共同開発<br>AIスキル</strong><small>作業・検証・報告の手順</small></a>'}${list('resource',currentProject.id).filter(e=>e.payload.category===kind).map(e=>`<button class="resource-book ${kind==='slides'?'mustard':kind==='spec'?'blue':'green'}" data-resource="${e.id}"><span>${e.payload.attachments?.length?'FILE':e.payload.url?'LINK':'TEXT'}</span><strong>${esc(e.payload.title)}</strong><small>${esc(e.payload.description)}</small></button>`).join('')}</div><div class="shelf-plank"></div></section>`).join('')}</div>`}
function presentation(){return heading('presentation',currentProject?`<button class="primary" data-action="newResource" ${canEdit()?'':'disabled'}>＋ チームのプレゼン資料を追加</button>`:'')+presentationRoomHTML()+(currentProject?`<section class="shelf presentation-team"><div class="shelf-heading"><span>▥</span><div><h2>チームのプレゼン資料</h2><p>資料部屋のプレゼン棚と共有しています。</p></div></div><div class="shelf-items">${list('resource',currentProject.id).filter(e=>e.payload.category==='slides').map(e=>`<button class="resource-book mustard" data-resource="${e.id}"><span>${e.payload.attachments?.length?'FILE':e.payload.url?'LINK':'TEXT'}</span><strong>${esc(e.payload.title)}</strong><small>${esc(e.payload.description)}</small></button>`).join('')||'<p class="muted">作った資料を追加すると、チームで共有できます。</p>'}</div><div class="shelf-plank"></div></section>`:'');}
function meetings(){const items=list('meeting',currentProject.id).sort((a,b)=>a.payload.date.localeCompare(b.payload.date));const today=new Date().toLocaleDateString('sv-SE');const upcoming=items.filter(e=>e.payload.date>=today);return heading('meeting',`<button class="primary" data-action="newMeeting" ${canEdit()?'':'disabled'}>＋ 会議を記録</button>`)+`<div class="meeting-layout"><section class="panel"><div class="section-heading"><h2>会議カレンダー</h2><input type="month" id="calendar-month" aria-label="表示する月" value="${today.slice(0,7)}"></div><div class="calendar" id="calendar"></div><div class="section-heading"><h2>会議と議事録</h2><small>${items.length}件</small></div><div id="meeting-list">${items.map(meetingHTML).join('')||'<div class="empty">会議の日時・議題・議事録をここに残せます。</div>'}</div></section><aside class="panel"><span class="section-label">次の会議</span>${upcoming[0]?meetingHTML(upcoming[0]):'<h2>予定はありません</h2><p class="muted">会議を追加して、チームに共有しましょう。</p>'}<div class="divider"></div><h3>Teams連携</h3><p>Teamsで発行した会議URLを登録すると、この部屋から参加できます。</p><small class="muted">予定の自動作成・録音・文字起こし連携は未接続です。</small></aside></div>`}
function meetingHTML(e){const p=e.payload;return `<button class="meeting-card" data-meeting="${e.id}"><span class="meeting-date">${esc(p.date)}<small>${esc(p.time)}</small></span><div><h3>${esc(p.title)}</h3><p>${esc(p.agenda?.slice(0,70)||'議題未設定')}</p><span class="tag">${p.minutes?'議事録あり':'議事録待ち'}</span></div></button>`}
const guides={vscode:['VSCodeの環境構築','1. VSCodeを公式サイトからインストール\n2. Gitをインストールし、git --versionで確認\n3. プロジェクトに必要なNode.jsのバージョンをREADMEで確認\n4. git config --global user.name "名前"\n5. git config --global user.email "GitHubに登録したメール"\n6. VSCodeでプロジェクトフォルダを開く\n7. READMEに従って依存関係をインストール\n8. ローカルで起動し、動作を確認'],git:['cloneからpushまで','1. 開発部屋でリポジトリを設定\n2. git clone <リポジトリURL>\n3. cd <リポジトリ名>\n4. git switch -c feature/作業名\n5. 編集・実行・動作確認\n6. git diffで変更を確認\n7. git add <ファイル名>\n8. git commit -m "変更内容"\n9. git push -u origin <作業ブランチ名>\n10. GitHubでPRを作成し、もう1人にレビューを依頼'],agent:['AIエージェントの使い方','1. 対象タスクと完了条件を伝える\n2. README、ルール、仕様書を確認させる\n3. 必要なSKILL.mdを資料部屋から取得\n4. 変更範囲と制約を伝える\n5. 差分とテスト結果を確認\n6. 秘密情報・不要な変更がないか確認\n7. 人がレビューして反映する'],setup:['2人での共同利用を有効にする','1. Supabaseにプロジェクトを作成\n2. supabase/schema.sqlをSQL Editorで実行\n3. school_allowed_emailsに2人のメールを登録\n4. config.jsにProject URLと公開用publishable keyを設定\n5. Auth設定で学校の公開URLをSite URLとRedirect URLへ登録\n6. 2人が初回登録してメール確認\n7. 1人がプロジェクトを作成し、メンバー追加から2人目を招待\n8. 同じキャンバスを開いて、付箋とカーソルが同期することを確認\n\nservice_roleキーやGitHubトークンをconfig.jsに入れないでください。']};
function environment(){return heading('environment')+`<div class="guide-grid">${Object.entries(guides).map(([key,[name,body]],i)=>`<section class="panel guide-card"><span class="guide-number">${String(i+1).padStart(2,'0')}</span><h2>${name}</h2><p>${esc(body.split('\n')[0])}</p><button data-guide="${key}">手順書を開く</button></section>`).join('')}</div><section class="panel"><h2>2人の開発フロー</h2><p>タスクを選ぶ → 作業ブランチ → 開発・検証 → push → PR → 相手がレビュー → mainへ反映</p><p class="muted">AIスキルは資料部屋で管理。画面設計・振り返り・議事録は、各教室で共有できます。</p></section>`}
async function activate(){cleanup?.();cleanup=null;if(!state.user||!state.profile)return render();const r=route();currentRoom=['campus',...rooms.map(r=>r[0])].includes(r.r)?r.r:'campus';subtab=['board','refine','retro'].includes(r.tab)?r.tab:'board';let project=state.projects.find(p=>p.id===r.p);if(r.p&&!project){currentProject=null;render();notify('プロジェクトが見つからないか、閲覧権限がありません。');return}project=project||state.projects[0];if(project){await selectProject(project.id);currentProject=project;await joinRoom(project.id,currentRoom==='scrum'?`${currentRoom}-${subtab}`:currentRoom)}else currentProject=null;render();window.scrollTo(0,0);if(r.item&&!['communication','presentation'].includes(currentRoom)){const task=state.entities.find(e=>e.id===r.item);if(task?.kind==='task')editTask(task);else if(task?.kind==='meeting')editMeeting(task);else notify('この項目は見つからないか削除されています。')}}
function render(){if(rendering)return;rendering=true;try{if(!state.user){login();return}if(state.error){$('#app').innerHTML=`<div class="admission"><h1>入校の確認</h1><p>${esc(state.error)}</p><button id="logout-error">ログアウト</button></div>`;$('#logout-error').onclick=async()=>{state.error='';await signOut()};return}if(!state.profile){onboarding();return}shell(currentRoom==='campus'?campus():currentRoom==='study'?heading('study')+studyRoomHTML():currentRoom==='presentation'?presentation():!currentProject?heading(currentRoom)+'<div class="empty">プロジェクトを作成するか、一覧から選んでください。</div>':currentRoom==='dev'?dev():currentRoom==='design'?heading('design')+canvasHTML('design',currentProject.id):currentRoom==='scrum'?scrum():currentRoom==='library'?library():currentRoom==='meeting'?meetings():currentRoom==='communication'?heading('communication')+communityChatHTML():environment());bindPage()}finally{rendering=false}}
function login(){const online=!!state.client;$('#app').innerHTML=`<div class="admission"><div class="admission-sign"><span class="brand-mark">DE</span><small>WELCOME TO OUR CAMPUS</small><h1>デジタル<br>エンジニア学校</h1><p>部署を超えて、一緒につくる。<br>開発・デザイン・スクラムの共同キャンパス。</p><div class="admission-room-labels">開発部屋 / デザイン部屋 / スクラム部屋<br>資料部屋 / 会議室 / コミュニケーションルーム / 勉強部屋 / プレゼンルーム<br>学校運営・サポート：環境委員会</div></div><section class="admission-form"><span class="section-label">入校受付</span><h2>${online?'おかえりなさい':'校内を体験する'}</h2>${online?`<form id="login-form">${input('email','メールアドレス','','email',true)}${input('password','パスワード','','password',true)}<p class="muted">初回登録後、この端末ではログインを維持します。</p><p class="form-error" role="alert"></p><div class="row"><button class="primary" name="login">ログイン</button><button name="signup">初回登録</button><button type="button" id="login-link">メールでログイン</button></div></form>`:'<p>8つの教室と環境委員会を見て、タスクやキャンバスを試せます。内容はこの端末だけに保存されます。</p><button class="primary" id="preview-button">プレビューに入校</button><div class="divider"></div><p class="muted">共同利用の接続設定はまだありません。設定後にアカウント登録と同期が使えるようになります。</p>'}</section></div>`;if(online)$('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);e.submitter.disabled=true;try{const message=await signIn(f.get('email'),f.get('password'),e.submitter.name==='signup');if(message)notify(message)}catch(err){$('.form-error').textContent=err.message}finally{e.submitter.disabled=false}};else $('#preview-button').onclick=()=>enterPreview();if(online)$('#login-link').onclick=async()=>{const email=$('#login-form input[name=email]');if(!email.reportValidity())return;try{await requestLoginLink(email.value);notify('ログインメールを送信しました。受信箱を確認してください。')}catch(error){$('.form-error').textContent=error.message}};}
function onboarding(profile=state.profile){$('#app').innerHTML=`<div class="onboarding"><span class="section-label">初回だけの入校準備</span><h1>あなたの名札をつくろう。</h1><p>30キャラから、あなたの相棒を選ぼう。教室と共同キャンバスに表示されます。</p><form id="profile-form">${input('name','表示名',profile?.name||'','text',true)}${!state.preview?input('newPassword','ログイン用パスワード（任意・8文字以上）','','password'):''}<fieldset><legend>アバターを選択</legend>${['アニメ風','手描きアニメ風','3Dアニメ風'].map((name,row)=>`<h3>${name} <small>人間5人・動物5匹</small></h3><div class="avatar-options">${Array.from({length:10},(_,col)=>col).map(col=>{const i=row*10+col;return `<label><input type="radio" name="avatar" aria-label="${name}のキャラクター ${col+1}" value="${i}" ${i===Number(profile?.avatar||0)?'checked':''}>${avatar(i,'',true)}</label>`}).join('')}</div>`).join('')}</fieldset><p class="form-error" role="alert"></p><div class="row"><button class="primary">名札を保存して入校</button>${profile?'<button type="button" id="cancel-profile">校内ホームに戻る</button>':''}</div></form></div>`;if($('#cancel-profile'))$('#cancel-profile').onclick=()=>navigate('campus');$('#profile-form').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.target);try{if(f.get('newPassword'))await setAccountPassword(String(f.get('newPassword')));await saveProfile({name:String(f.get('name')).trim(),department:'',avatar:Number(f.get('avatar'))})}catch(e){$('.form-error').textContent=e.message}}}
async function action(name){try{if(name==='newProject'){dialog('新しいプロジェクト',input('name','プロジェクト名','','text',true)+textArea('description','概要・目標')+select('visibility','公開範囲',[['private','Private · 招待メンバーのみ'],['public','Public · 学校内の全員が閲覧']],'private')+input('repo','GitHubリポジトリURL（任意）','','url')+'<p class="muted">Publicでも編集は招待メンバーのみ。ソースコードの公開範囲はGitHub側で設定します。</p>',async f=>{const repo=String(f.get('repo')).trim();if(repo&&!repoSlug(repo))throw Error('https://github.com/所有者/リポジトリ の形式で入力してください');const p=await createProject({name:String(f.get('name')).trim(),department:'',description:f.get('description'),visibility:f.get('visibility'),repo});navigate('campus',p.id)},'プロジェクトを作る');}
 else if(name==='projectSettings'){if(state.role!=='owner')throw Error('所有者のみ変更できます');dialog('プロジェクト設定',input('name','プロジェクト名',currentProject.name,'text',true)+textArea('description','概要・目標',currentProject.description)+select('visibility','公開範囲',[['private','Private · 招待メンバーのみ'],['public','Public · 学校内の全員が閲覧']],currentProject.visibility)+'<p class="muted">PublicからPrivateにすると、招待されていない学校メンバーは閲覧できなくなります。</p>',async f=>{const name=String(f.get('name')).trim();if(!name)throw Error('プロジェクト名を入力してください');await updateProject(currentProject.id,{name,description:f.get('description'),visibility:f.get('visibility')});notify('プロジェクト設定を保存しました')});}
 else if(name==='members'){const members=await projectMembers(currentProject.id);dialog('メンバーと権限',`<p>このプロジェクトの参加者です。URLの共有だけでは編集権限は付与されません。</p><div class="member-list">${members.map(m=>`<div class="member-row">${avatar(m.avatar,m.name)}<strong>${esc(m.name)}</strong><span class="tag">${{owner:'所有者',editor:'編集者',viewer:'閲覧者'}[m.role]}</span></div>`).join('')}</div><p class="muted">${state.preview?'端末内プレビューでは自分のみです。':'権限変更は所有者が「共同開発者を招待」で同じメールを指定して行えます。'}</p>`,async()=>{},'閉じる');}
 else if(name==='backup'){download('school-project-backup.json',JSON.stringify(projectBackup(currentProject.id),null,2),'application/json');notify('プロジェクトのバックアップを書き出しました');}
 else if(name==='restore'){dialog('バックアップから新規作成','<label>バックアップJSON<input name="file" type="file" accept=".json,application/json" required></label><p class="muted">現在のプロジェクトは残したまま、Privateの新規プロジェクトとして復元します。メンバー権限は復元しません。</p>',async f=>{const file=f.get('file');if(file.size>10*1024*1024)throw Error('10MB以下のJSONを選んでください');const value=validateBackup(JSON.parse(await file.text()));const project=await createProject({...value.project,name:value.project.name+'（復元）',department:'',visibility:'private'});const ids=new Map(value.entities.map(e=>[e.id,id()]));let count=0;try{for(const e of value.entities){const payload={...e.payload};if(payload.epic)payload.epic=ids.get(payload.epic)||'';await put(project.id,e.kind,payload,ids.get(e.id),0);count++}}catch(error){navigate('campus',project.id);throw Error(`${count}件まで復元しました。残りの復元に失敗: ${error.message}`)}navigate('campus',project.id);notify(`${count}件を新しいプロジェクトに復元しました`);},'新規プロジェクトに復元');}
 else if(name==='share')await share();else if(name==='logout')await signOut();else if(name==='profile'){onboarding(state.profile)}else if(name==='openBoard')navigate('scrum',currentProject?.id,'board');else if(name==='openRules')navigate('dev');else if(name==='setup')showGuide('setup');else if(name==='refresh'){const {load}=await import('./store.js');await load();render();notify('一覧を更新しました')}
 else if(name==='invite'){const invitations=await projectInvitations(currentProject.id);dialog('共同開発者をメールで招待',input('email','招待するメールアドレス','','email',true)+select('role','権限',[['editor','編集者 · コード・タスク等を編集'],['viewer','閲覧者 · 状況を確認']],'editor')+`<p class="muted">未登録の方も招待できます。有効期限は7日間。メールのリンクから入校すると権限が付与されます。</p><details><summary>招待一覧 (${invitations.length})</summary>${invitations.map(i=>`<div class="invitation-row"><strong>${esc(i.email)}</strong><span>${i.role==='editor'?'編集者':'閲覧者'} · ${i.status==='accepted'?'参加済み':i.status==='cancelled'?'取り消し':new Date(i.expires_at)<new Date()?'期限切れ':i.delivery==='sent'?'メール送信済み':i.delivery==='failed'?'メール未送信':'送信処理中'}</span>${i.status==='pending'?`<button type="button" data-cancel-invite="${i.id}">取り消す</button>`:''}</div>`).join('')||'<p>まだ招待はありません。</p>'}</details>`,async f=>{const result=await inviteMember(currentProject.id,f.get('email'),f.get('role'));dialog(result.delivery==='sent'?'招待メールを送信しました':'招待を保存しました（メール未送信）',`<p>${esc(result.message)}</p><p>招待先: ${esc(String(f.get('email')))}</p><label>プロジェクトURL<input readonly value="${esc(result.url)}"></label><p class="muted">このURLだけでは参加権限は付与されません。招待したメールアドレスの確認とログインが必要です。</p>${result.delivery==='sent'?'':`<a class="button" href="https://supabase.com/dashboard/project/rfhgmszrqoipuryigpjg/auth/smtp" target="_blank" rel="noopener noreferrer">管理者用：メール送信設定を開く</a>`}`,async()=>{},'閉じる');return false;},'招待メールを送信');$$('[data-cancel-invite]').forEach(button=>button.onclick=async()=>{try{await cancelInvitation(button.dataset.cancelInvite);button.closest('.invitation-row').querySelector('span').textContent='取り消しました';button.remove();}catch(error){notify(error.message)}});}
 else if(name==='newTask')editTask();else if(name==='newRetro')editRetro();else if(name==='newMeeting')editMeeting();else if(name==='newResource')editResource();else if(name==='newCode')editCodeMeta();
 else if(name==='repo'){dialog('GitHubリポジトリ',input('repo','URL',currentProject.repo,'url',true),async f=>{const url=f.get('repo');if(!repoSlug(url))throw Error('GitHubのリポジトリURLを入力してください');const {updateProject}=await import('./store.js');await updateProject(currentProject.id,{repo:url});currentProject.repo=url;render()})}
 else if(name==='openEditor'||name==='codespaces'){const slug=repoSlug(currentProject.repo);if(!slug)throw Error('リポジトリを設定してください');window.open(name==='openEditor'?`https://github.dev/${slug}`:`https://github.com/codespaces/new?repo=${encodeURIComponent(slug)}`,'_blank','noopener,noreferrer')}
 else if(name==='clone'){const slug=repoSlug(currentProject.repo);if(!slug)throw Error('リポジトリを設定してください');dialog('このリポジトリで開発を始める',`<pre>git clone https://github.com/${esc(slug)}.git\ncd ${esc(slug.split('/')[1])}\ncode .</pre><p>VSCodeのターミナルで実行し、READMEの起動手順に進んでください。</p><p class="muted">GitHub.devは編集用です。ターミナルで実行する場合はVSCodeまたはCodespacesを使います。</p>`,async()=>{},'閉じる')}
 }catch(e){notify(e.message)}}
function repoSlug(value){try{const u=new URL(value);if(u.hostname!=='github.com'||u.protocol!=='https:')return null;const path=u.pathname.replace(/^\/+|\/+$/g,'').replace(/\.git$/,'');return /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(path)?path:null}catch{return null}}
function editTask(entity){const p=entity?.payload||{},epics=list('task',currentProject.id).filter(e=>e.payload.type==='epic'&&e.id!==entity?.id);dialog(entity?'タスクの詳細':'新しいカード',input('title','タイトル',p.title,'text',true)+`<div class="two-col">${select('type','種類',[['task','タスク'],['epic','エピック']],p.type||'task')}${select('status','状態',[['todo','これから'],['doing','進行中'],['review','レビュー'],['done','完了']],p.status||'todo')}</div>`+textArea('description','内容・完了条件',p.description)+`<div class="two-col">${input('assignee','担当者',p.assignee)}${input('due','期限',p.due,'date')}</div>`+select('epic','所属エピック',[['','なし'],...epics.map(e=>[e.id,e.payload.title])],p.epic||'')+select('priority','優先度',[['normal','通常'],['high','高'],['low','低']],p.priority||'normal')+(entity?`<div class="row"><button type="button" id="task-share">URLを共有</button>${canEdit()?'<button type="button" class="danger" id="task-delete">削除</button>':''}</div>`:''),async f=>{if(!canEdit())return;await put(currentProject.id,'task',Object.fromEntries(f),entity?.id,entity?.version);render()},canEdit()?'保存':'閉じる');if(entity){$('#task-share').onclick=()=>share('scrum',entity.id);if(canEdit())$('#task-delete').onclick=()=>dialog('カードを削除',`<p>${esc(p.title)}を削除します。</p>`,async()=>{await remove(entity);render()},'削除')}if(!canEdit())$$('#modal input,#modal textarea,#modal select').forEach(e=>e.disabled=true)}
function editRetro(entity){const p=entity?.payload||{};dialog(entity?'振り返りを編集':'振り返りの付箋',select('column','分類',[['keep','Keep · 続けたいこと'],['problem','Problem · 困ったこと'],['try','Try · 次に試すこと']],p.column||'keep')+input('sprint','スプリント名',p.sprint)+textArea('text','内容',p.text),async f=>{if(!canEdit())return;const v=Object.fromEntries(f);if(!v.text.trim())throw Error('内容を入力してください');await put(currentProject.id,'retro',{...v,author:p.author||state.profile.name,votes:p.votes||[]},entity?.id,entity?.version);render()},canEdit()?'保存':'閉じる');if(!canEdit())$$('#modal input,#modal textarea,#modal select').forEach(e=>e.disabled=true)}
function editResource(entity){const p=entity?.payload||{};dialog(entity?'棚の資料':'資料・スキルを追加',input('title','タイトル',p.title,'text',true)+select('category','棚',[['slides','プレゼン資料'],['spec','仕様書'],['skill','AIスキル']],p.category||'slides')+input('url','ファイル・ページのURL（任意）',p.url,'url')+input('description','説明',p.description)+textArea('content','テキスト・スキル本文',p.content)+`<label>ファイルを添付（形式自由・1件20MBまで）<input type="file" name="attachments" multiple></label><div>${(p.attachments||[]).map((a,i)=>`<button type="button" data-file-index="${i}">↓ ${esc(a.name)}</button>`).join('')}</div>`+(entity?`<div class="row">${safeUrl(p.url)?`<a class="button" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(p.url))}">資料を開く</a>`:''}<button type="button" id="resource-download">本文をダウンロード</button></div>`:''),async f=>{if(!canEdit())return;const v=Object.fromEntries(f);v.attachments=[...(p.attachments||[])];for(const file of f.getAll('attachments'))if(file.size)v.attachments.push(await uploadAttachment(file,currentProject.id));if(v.url&&!safeUrl(v.url))throw Error('HTTPSのURLを入力してください');await put(currentProject.id,'resource',v,entity?.id,entity?.version);render()},canEdit()?'保存':'閉じる');$$('[data-file-index]').forEach(b=>b.onclick=()=>downloadAttachment(p.attachments[Number(b.dataset.fileIndex)]).catch(e=>notify(e.message)));if(entity)$('#resource-download').onclick=()=>download((p.title||'resource')+'.md',p.content||'');if(!canEdit())$$('#modal input,#modal textarea,#modal select').forEach(e=>e.disabled=true)}
function editMeeting(entity){const p=entity?.payload||{};dialog(entity?'会議と議事録':'会議を追加',input('title','会議名',p.title,'text',true)+`<div class="two-col">${input('date','日付',p.date||new Date().toLocaleDateString('sv-SE'),'date',true)}${input('time','開始時刻',p.time||'10:00','time',true)}</div>`+input('url','Teamsなどの会議URL',p.url,'url')+textArea('agenda','議題・参加者',p.agenda)+textArea('minutes','議事録・決定事項',p.minutes)+textArea('actions','次のアクション',p.actions)+(entity?`<div class="row">${safeUrl(p.url)?`<a class="button primary" href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener noreferrer">会議に参加</a>`:''}<button type="button" id="meeting-share">URLを共有</button><button type="button" id="minutes-download">議事録保存</button></div>`:''),async f=>{if(!canEdit())return;const v=Object.fromEntries(f);v.attachments=[...(p.attachments||[])];for(const file of f.getAll('attachments'))if(file.size)v.attachments.push(await uploadAttachment(file,currentProject.id));if(v.url&&!safeUrl(v.url))throw Error('HTTPSの会議URLを入力してください');await put(currentProject.id,'meeting',v,entity?.id,entity?.version);render()},canEdit()?'保存':'閉じる');if(entity){$('#meeting-share').onclick=()=>share('meeting',entity.id);$('#minutes-download').onclick=()=>download(`${p.title}-議事録.md`,`# ${p.title}\n\n日時: ${p.date} ${p.time}\n\n## 議題\n${p.agenda}\n\n## 決定事項・議事録\n${p.minutes}\n\n## 次のアクション\n${p.actions}`)}if(!canEdit())$$('#modal input,#modal textarea,#modal select').forEach(e=>e.disabled=true)}
function editCodeMeta(){dialog('コード下書きを追加',input('path','ファイル名','src/example.js','text',true)+textArea('code','コード','// 共同開発の下書き\n'),async f=>{const v=Object.fromEntries(f);await put(currentProject.id,'code',v);render()})}
function showCode(entity){const p=entity.payload;$('#code-editor').innerHTML=`<form id="code-form"><div class="section-heading"><strong>${esc(p.path)}</strong><button class="primary" ${canEdit()?'':'disabled'}>下書きを保存</button></div><textarea class="code-text" name="code" spellcheck="false" aria-label="コード下書き" ${canEdit()?'':'readonly'}>${esc(p.code)}</textarea></form><div id="ai-assistant"></div>`;bindAI({projectId:currentProject.id,entity,notify,dialog});$('#code-form').onsubmit=async e=>{e.preventDefault();try{entity=await put(currentProject.id,'code',{...p,code:new FormData(e.target).get('code')},entity.id,entity.version);notify('校内の下書きを保存しました')}catch(err){notify(err.message)}}}
function showGuide(key){const [name,body]=guides[key];dialog(name,`<pre class="guide-text">${esc(body)}</pre><button type="button" id="guide-download">手順書を保存</button>`,async()=>{},'閉じる');$('#guide-download').onclick=()=>download(name+'.md',`# ${name}\n\n${body}`)}
function drawCalendar(value){const [y,m]=value.split('-').map(Number),start=new Date(y,m-1,1).getDay(),days=new Date(y,m,0).getDate();$('#calendar').innerHTML=['日','月','火','水','木','金','土'].map(d=>`<div class="calendar-day-name">${d}</div>`).join('')+Array.from({length:start},()=>'<div class="calendar-blank"></div>').join('')+Array.from({length:days},(_,i)=>{const date=`${y}-${String(m).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;const items=list('meeting',currentProject.id).filter(e=>e.payload.date===date);return `<button class="calendar-cell ${items.length?'has-event':''}" data-day="${date}"><span>${i+1}</span>${items.map(e=>`<small>${esc(e.payload.title)}</small>`).join('')}</button>`}).join('');$$('[data-day]').forEach(b=>b.onclick=()=>{const items=list('meeting',currentProject.id).filter(e=>e.payload.date===b.dataset.day);$('#meeting-list').innerHTML=items.map(meetingHTML).join('')||`<div class="empty">${b.dataset.day}の会議はありません。</div>`;$$('[data-meeting]').forEach(n=>n.onclick=()=>editMeeting(state.entities.find(e=>e.id===n.dataset.meeting)))})}
function bindPage(){bindExpansions();if(currentRoom==='presentation'){cleanup?.();cleanup=bindPresentationRoom({tab:route().tab,item:route().item,onOpen:(tab,item)=>navigate('presentation',currentProject?.id,tab,item),notify});}if(currentRoom==='communication'&&currentProject){cleanup?.();cleanup=bindCommunityChat({projectId:currentProject.id,topicId:route().item,onOpen:topic=>navigate('communication',currentProject.id,null,topic),notify,dialog});}if(currentRoom==='study'){cleanup?.();cleanup=bindStudyRoom({notify});}if(currentRoom==='campus'){cleanup?.();cleanup=bindCampusScene({rooms:rooms.filter(r=>r[0]!=='environment'),onEnter:room=>navigate(room,currentProject?.id)});}if(currentRoom==='dev'&&currentProject){loadBranches();bindTerminal();} $$('[data-project]').forEach(b=>b.onclick=()=>navigate('campus',b.dataset.project));$$('[data-tab]').forEach(b=>b.onclick=()=>navigate('scrum',currentProject.id,b.dataset.tab));$$('[data-guide]').forEach(b=>b.onclick=()=>showGuide(b.dataset.guide));$$('[data-code]').forEach(b=>b.onclick=()=>showCode(state.entities.find(e=>e.id===b.dataset.code)));$$('[data-resource]').forEach(b=>b.onclick=()=>editResource(state.entities.find(e=>e.id===b.dataset.resource)));$$('[data-meeting]').forEach(b=>b.onclick=()=>editMeeting(state.entities.find(e=>e.id===b.dataset.meeting)));$$('[data-retro-edit]').forEach(b=>b.onclick=()=>editRetro(state.entities.find(e=>e.id===b.dataset.retroEdit)));
 $$('[data-vote]').forEach(b=>b.onclick=async()=>{const e=state.entities.find(e=>e.id===b.dataset.vote),v=e.payload.votes||[];try{await put(currentProject.id,'retro',{...e.payload,votes:v.includes(state.user.id)?v.filter(id=>id!==state.user.id):[...v,state.user.id]},e.id);render()}catch(err){notify(err.message)}});
 $$('[data-to-task]').forEach(b=>b.onclick=()=>{const e=state.entities.find(e=>e.id===b.dataset.toTask);dialog('改善をタスクにする',input('title','タイトル',e.payload.text,'text',true),async f=>{await put(currentProject.id,'task',{title:f.get('title'),description:`振り返りから: ${e.payload.text}`,status:'todo',priority:'normal',type:'task',assignee:'',due:'',epic:''});notify('スクラムボードにタスクを追加しました')})});
 $$('[data-task]').forEach(card=>{const open=()=>editTask(state.entities.find(e=>e.id===card.dataset.task));card.onclick=open;card.onkeydown=e=>{if(e.key==='Enter')open()};card.ondragstart=e=>{e.dataTransfer.setData('text/plain',card.dataset.task);e.dataTransfer.effectAllowed='move'}});
 $$('[data-status]').forEach(col=>{col.ondragover=e=>{if(canEdit()){e.preventDefault();col.classList.add('drag-over')}};col.ondragleave=()=>col.classList.remove('drag-over');col.ondrop=async event=>{event.preventDefault();col.classList.remove('drag-over');const e=state.entities.find(e=>e.id===event.dataTransfer.getData('text/plain'));if(e?.kind==='task')try{await put(currentProject.id,'task',{...e.payload,status:col.dataset.status},e.id);render()}catch(err){notify(err.message)}}});
 if($('#canvas-world')){cleanup?.();cleanup=bindCanvas({projectId:currentProject.id,mode:currentRoom==='design'?'design':'refine',notify,dialog,download})}
 if($('#calendar-month')){$('#calendar-month').onchange=e=>{if(e.target.value)drawCalendar(e.target.value)};drawCalendar($('#calendar-month').value)}renderPresence();renderDirectory();}
function renderDirectory(){const root=$('#hallway-roster');if(!root)return;if(state.preview){root.innerHTML='';return}root.innerHTML='<span class="section-label">今の教室</span>'+state.directory.map(p=>`<span class="roster-person">${avatar(p.avatar,p.name)}<span>${esc(p.name)}<small>${esc(p.room==='campus'?'校内案内':rooms.find(r=>p.room.startsWith(r[0]))?.[2]||p.room)}</small></span></span>`).join('');}
function renderPresence(){if(!$('#presence'))return;const peers=state.preview?[{name:state.profile?.name,avatar:state.profile?.avatar}]:state.peers;$('#presence').innerHTML=peers.map(p=>avatar(p.avatar,p.name)).join('');$('#presence').title=peers.map(p=>p.name).join('、');}
state.listeners.push((event,payload)=>{if(event==='auth'){activate().catch(e=>notify(e.message))}else if(event==='presence')renderPresence();else if(event==='directory')renderDirectory();else if(event==='connection'&&$('#connection'))$('#connection').textContent=payload;else if(event==='data'&&!['communication','study'].includes(currentRoom)&&!$('#canvas-world')&&!document.activeElement?.closest('#code-editor'))render()});
window.addEventListener('hashchange',()=>activate().catch(e=>notify(e.message)));
try{await initialize();await activate()}catch(e){state.error=e.message;render();notify('接続に失敗しました: '+e.message)}

function bindExpansions(){document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{const target=document.querySelector('.'+b.dataset.expand);const active=target.classList.toggle('workspace-expanded');b.textContent=active?'⤡ 元のサイズに戻す':'⛶ 作業スペースを拡大';});}
async function loadBranches(){const root=$('#branch-state');if(!root)return;const match=currentProject.repo?.match(/github\.com\/([^/]+)\/([^/#?]+)/);if(!match){root.textContent='リポジトリを設定するとGitHubのブランチを表示できます。';return}const owner=match[1],repo=match[2].replace(/\.git$/,'');root.textContent='GitHubのブランチを取得中…';try{const responses=await Promise.all([fetch(`https://api.github.com/repos/${owner}/${repo}`),fetch(`https://api.github.com/repos/${owner}/${repo}/branches?per_page=100`)]);if(responses.some(r=>!r.ok))throw Error('ブランチを取得できません。非公開リポジトリはGitHubで確認してください。');const [info,branches]=await Promise.all(responses.map(r=>r.json()));if(!root.isConnected)return;root.innerHTML=`<strong>🌿 GitHubのブランチ</strong><select id="branch-selector">${branches.map(b=>`<option value="${esc(b.name)}" ${b.name===info.default_branch?'selected':''}>${esc(b.name)}${b.name===info.default_branch?'（既定）':''}</option>`).join('')}</select><div id="branch-details"></div><p class="muted">校内コードは下書きです。端末・Codespacesの現在ブランチは自動取得できません。開発環境で git branch --show-current を実行してください。</p>`;const update=()=>{const b=branches.find(b=>b.name===$('#branch-selector').value);$('#branch-details').innerHTML=`参照位置：<code>${esc(b.name)}</code> → <code>${esc(b.commit.sha.slice(0,7))}</code> <a target="_blank" rel="noopener noreferrer" href="https://github.com/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/tree/${encodeURIComponent(b.name)}">GitHubで開く ↗</a>`};$('#branch-selector').onchange=update;update();}catch(e){if(root.isConnected)root.textContent=e.message;}}
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.workspace-expanded').forEach(n=>{n.classList.remove('workspace-expanded');const b=n.querySelector('[data-expand]');if(b)b.textContent='⛶ 作業スペースを拡大';});});

function bindTerminal(){
 const form=$('#terminal-form'),output=$('#terminal-output'),input=$('#terminal-command');if(!form)return;
 const history=[];let position=0;
 const write=text=>{const line=document.createElement('pre');line.textContent=text;output.append(line);while(output.children.length>100)output.firstElementChild.remove();output.scrollTop=output.scrollHeight;};
 write('開発机のコマンドパネルへようこそ。help で対応コマンドを表示します。');
 input.onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();position=Math.max(0,Math.min(history.length,position+(e.key==='ArrowUp'?-1:1)));input.value=history[position]||'';}};
 form.onsubmit=async e=>{e.preventDefault();const command=input.value.trim();if(!command)return;history.push(command);position=history.length;input.value='';write('PS 学校\\開発机> '+command);const button=form.querySelector('button');button.disabled=true;input.disabled=true;
 try{
 if(/^(clear|cls)$/.test(command)){output.replaceChildren();return;}
 if(command==='help'){write('git branch / git branch -a : GitHubのブランチ一覧\ngit log / git log --oneline : 選択したブランチの最新10件の履歴\ngit remote -v : 登録されたGitHub URL\ngit ls-remote : GitHubのブランチとコミット位置\ngit status : 校内下書きとGit環境の案内\nclear / cls : 表示を消去\n↑ / ↓ : 入力履歴\nclone・switch・add・commit・push・pullは右上からCodespacesを開いて実行');return;}
 if(command==='git remote -v'){const slug=repoSlug(currentProject.repo);if(!slug)throw Error('先にGitHubリポジトリを設定してください。');write('登録先（Git実行環境のoriginとは別）\nhttps://github.com/'+slug+'.git');return;}
 if(command==='git status'){write('校内コード下書き: '+list('code',currentProject.id).length+'ファイル\n下書きは学校のデータベースに保存されています。Gitの作業ツリー・ステージ状態はCodespaces / VSCodeで git status を実行して確認してください。');return;}
 const slug=repoSlug(currentProject.repo);if(!slug)throw Error('先にGitHubリポジトリを設定してください。');
 const branches=['git branch','git branch -a','git ls-remote'].includes(command),logs=['git log','git log --oneline'].includes(command);
 if(!branches&&!logs)throw Error('このパネルでは未対応のコマンドです。help を確認するか、Codespaces / VSCodeのターミナルで実行してください。');
 const selected=$('#branch-selector')?.value;
 const endpoint=branches?'branches?per_page=100':'commits?per_page=10'+(selected?'&sha='+encodeURIComponent(selected):'');
 const response=await fetch('https://api.github.com/repos/'+slug+'/'+endpoint,{signal:AbortSignal.timeout(15000)});
 if(!response.ok)throw Error('GitHubから取得できません（HTTP '+response.status+'）。非公開リポジトリはCodespaces / VSCodeで確認してください。');
 const rows=await response.json();if(!output.isConnected)return;
 write(branches?rows.map(b=>command==='git ls-remote'?b.commit.sha+'  refs/heads/'+b.name:(b.name===selected?'→ ':'  ')+b.name).join('\n')+'\n※ GitHub上の参照情報。→ は画面で選択したブランチです。先頭100件まで表示。':rows.map(c=>c.sha.slice(0,7)+' '+c.commit.message.split('\n')[0]).join('\n'));
 }catch(error){write(error.name==='TimeoutError'?'取得がタイムアウトしました。再実行してください。':error.message);}
 finally{button.disabled=false;input.disabled=false;if(input.isConnected)input.focus();}
 };
}
